import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"The game — boards, players, and the learned-policy loop","description":"","frontmatter":{},"headers":[],"relativePath":"graphopt/explanation/the-game.md","filePath":"vendored/graphopt/explanation/the-game.md"}`),a={name:`graphopt/explanation/the-game.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="the-game-—-boards-players-and-the-learned-policy-loop" tabindex="-1">The game — boards, players, and the learned-policy loop <a class="header-anchor" href="#the-game-—-boards-players-and-the-learned-policy-loop" aria-label="Permalink to “The game — boards, players, and the learned-policy loop”">​</a></h1><p>Because programs, rules, and derivations are all values in one calculus, <em>discovery itself</em> is a game: observe a state, play a move, get a report, repeat until done. <code>gamekit</code> names that shape once and puts the drivers over it.</p><h2 id="the-board-protocol" tabindex="-1">The <code>Board</code> protocol <a class="header-anchor" href="#the-board-protocol" aria-label="Permalink to “The Board protocol”">​</a></h2><div class="language-python"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">class</span><span style="--shiki-dark:#C5C5C5;--shiki-light:#6F42C1;"> Board</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">(</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">Protocol</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">):</span></span>
<span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">    def</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> observe</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">(</span><span style="--shiki-dark:#FFFFFF;--shiki-dark-font-style:italic;--shiki-light:#24292E;--shiki-light-font-style:inherit;">self</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">)</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;"> -&gt;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;"> state</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> ...</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#62687b;--shiki-light-font-style:inherit;">          #</span><span style="--shiki-dark:#BBBBBB;--shiki-dark-font-style:italic;--shiki-light:#62687b;--shiki-light-font-style:inherit;"> state.done ends the episode</span></span>
<span class="line"><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">    def</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;"> step</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">(</span><span style="--shiki-dark:#FFFFFF;--shiki-dark-font-style:italic;--shiki-light:#24292E;--shiki-light-font-style:inherit;">self</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">,</span><span style="--shiki-dark:#FFFFFF;--shiki-dark-font-style:italic;--shiki-light:#24292E;--shiki-light-font-style:inherit;"> action</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">)</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;"> -&gt;</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;"> (</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">state</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">,</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;"> report</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">):</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> ...</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#62687b;--shiki-light-font-style:inherit;">   #</span><span style="--shiki-dark:#BBBBBB;--shiki-dark-font-style:italic;--shiki-light:#62687b;--shiki-light-font-style:inherit;"> report: reward + terminal</span></span></code></pre></div><p>One contract, every domain. Three drivers ride on it:</p><ul><li><code>run_episode(board, player, budget)</code> — play one episode, get a <code>Trajectory</code>.</li><li><code>evaluate(arms, cases, board_of, *, budget)</code> — compare players under identical cases.</li><li><code>train_policy(player, cases, board_of, *, budget)</code> — REINFORCE over episode returns.</li></ul><p>A new domain is data + a small adapter: a <code>case -&gt; Board</code> factory and a featurizer. The domain registry (<code>mlopt_discovery.play.DOMAINS</code>) holds the boards — <code>meta</code>/<code>joint</code>/<code>search</code>/<code>torch</code>/<code>gen</code>/<code>open</code>/<code>player</code> — played through one CLI (the <code>kernel</code> domain moved out to <code>handl-lang/kernelopt</code>, which seats itself into <code>DOMAINS</code> at <code>mlopt_kernel.play</code> import):</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">python</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> -m</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> mlopt_discovery.play</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> --domain</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> meta</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> --player</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> linear</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#62687b;--shiki-light-font-style:inherit;">   #</span><span style="--shiki-dark:#BBBBBB;--shiki-dark-font-style:italic;--shiki-light:#62687b;--shiki-light-font-style:inherit;"> eval-only</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">python</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> -m</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> mlopt_discovery.play</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> --domain</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> torch</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> --deliver</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#62687b;--shiki-light-font-style:inherit;">        #</span><span style="--shiki-dark:#BBBBBB;--shiki-dark-font-style:italic;--shiki-light:#62687b;--shiki-light-font-style:inherit;"> lower + verify the win</span></span></code></pre></div><h2 id="the-players" tabindex="-1">The players <a class="header-anchor" href="#the-players" aria-label="Permalink to “The players”">​</a></h2><p>The registry (<code>gamekit.players.registry</code>) names every playable arm — <code>random</code> (chance), <code>playbook</code> (scripted), <code>linear</code> (the trained linear prior), <code>neural</code>, <code>distilled</code> — each as a <code>PlayerSpec</code> (<code>name</code>/<code>kind</code>/ <code>boards</code>/<code>schema</code>/<code>train</code>/<code>artifact</code>/<code>record</code>/<code>variant</code>) with a <code>make(name, domain)</code> factory that raises <code>ValueError</code> on an unplayed board rather than silently running. The learned arm is a featurizer-injected <code>LinearPolicy</code>: state features + action features → a score per legal move.</p><p>The two-tier meta-game goes one level up: <code>PlayerArena</code> is a board whose <em>state is a player spec</em> — moves toggle feature parts, edit weight priors, set the child&#39;s learning rate, probe the trained child, and <code>extract()</code> pays the delta. The leaderboard measures every registered player on every board it can play under one paired protocol (see <a href="./../reference/leaderboard.html">the leaderboard</a>).</p><h2 id="the-learned-policy-loop" tabindex="-1">The learned-policy loop <a class="header-anchor" href="#the-learned-policy-loop" aria-label="Permalink to “The learned-policy loop”">​</a></h2><p>Inside <em>search</em>, a <code>Policy</code> only reorders the legal moves — every rule still fires, so the fixed point and the certificate are unchanged (evaluation never decides equivalence — see <a href="./evaluation.html">evaluation</a>). A trained linear prior ranks law candidates at ~4.7× the tuned heuristic&#39;s average precision (held-out); a distilled contraction-ordering player beats <code>opt_einsum</code>&#39;s randomized greedy at equal wall-clock. Neural arms lose to the linear/distilled players today — reported as measured, not tuned.</p><h2 id="the-referee-seam" tabindex="-1">The referee seam <a class="header-anchor" href="#the-referee-seam" aria-label="Permalink to “The referee seam”">​</a></h2><p>The split that keeps the game honest: <strong>the value spec is gamekit&#39;s; the measurement is the gauntlet&#39;s.</strong> <code>ScoringSpec</code>/<code>ScoreGate</code> declare the axes and thresholds (speed, memory, launch, params, win-rate) as <em>data</em>; <code>score(spec, measured)</code> consumes a plain <code>Mapping[str, float]</code> emitted by the measurement side. The game layer imports no measurement machinery and the measurement side never imports the value spec — an enforced import contract.</p><h2 id="why-a-game-at-all" tabindex="-1">Why a game at all <a class="header-anchor" href="#why-a-game-at-all" aria-label="Permalink to “Why a game at all”">​</a></h2><p>The claim under test is the <em>connection</em>: TASO/Isaria mint + verify rules offline; CompilerGym-style systems learn over fixed banks. mlopt&#39;s bank grows under play — a minted law that survives <a href="./the-gauntlet.html">the gauntlet</a> becomes a legal move in the next episode. The open research question is exactly that: can a player learn in a game that grows under it?</p>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};